<script setup lang="ts">import{onMounted,reactive,ref}from'vue';import PageHeader from'../../components/PageHeader.vue';import{client,errorMessage,requireData}from'../../../shared/api/client';import type{components}from'../../../shared/api/schema.gen';const values=ref<components['schemas']['GlossaryTerm'][]>([]);const form=reactive<components['schemas']['GlossaryTerm']>({id:crypto.randomUUID(),sourceText:'',targetText:'',language:'',source:'manual',documentId:''});const error=ref('');async function refresh(){values.value=requireData(await client.GET('/api/admin/glossary',{}))}onMounted(async()=>{try{await refresh()}catch(cause){error.value=errorMessage(cause)}});async function save(){try{requireData(await client.PUT('/api/admin/glossary',{body:form}));form.id=crypto.randomUUID();form.sourceText='';form.targetText='';await refresh()}catch(cause){error.value=errorMessage(cause)}}</script>
<template><PageHeader title="术语表"/><p v-if="error" class="text-danger">{{ error }}</p><form class="mb-6 grid gap-3 sm:grid-cols-4" @submit.prevent="save"><input v-model="form.sourceText" required class="nw-input" placeholder="原文"><input v-model="form.targetText" required class="nw-input" placeholder="译文"><input v-model="form.language" required class="nw-input" placeholder="语言代码"><button class="nw-button">添加术语</button></form><table class="w-full"><thead><tr><th>原文</th><th>译文</th><th>语言</th><th>来源</th></tr></thead><tbody><tr v-for="term in values" :key="term.id"><td>{{ term.sourceText }}</td><td>{{ term.targetText }}</td><td>{{ term.language }}</td><td>{{ term.source }}</td></tr></tbody></table></template>
